_editor_class["liu_10_mc_sc_ring"].render=function(self)
    local b = self.boss
    SetViewMode"world"
    if IsValid(b) then
        local extend_rate = 1 + 8 / 60
        local alpha = min(b.sc_ring_alpha or 144, 144)
        local exr1 = -0.5
        local bold = 1
        local main_radius = 160
        local timer, rov, cut, flag = b.timer, 4, 48, 1
        local pause = ext.pause_menu
        if pause and pause.IsKilled and pause:IsKilled() then
        	pause = false
        end
        local ringx = b._sc_ring_x or b.x
        local ringy = b._sc_ring_y or b.y
        if not pause then
        	local minspeed = b._sc_ring_minspeed or 0.5
        	local ratespeed = b._sc_ring_ratespeed or 0.08
        	local speed = Dist(ringx, ringy, b.x, b.y)
        	local angle = Angle(ringx, ringy, b.x, b.y)
        	speed = min(speed, max(speed * ratespeed, minspeed))
        	ringx = ringx + speed * cos(angle)
        	ringy = ringy + speed * sin(angle)
        end
        b._sc_ring_x = ringx
        b._sc_ring_y = ringy
        if not b.__is_waiting and b.__draw_sc_ring then
        	for i = 1, 16 do
        		SetImageState('bossring1' .. i, 'mul+add', Color(alpha, 255, 255, 255))
        	end
        	if timer < 90 then
        		if b.fxr and b.fxg and b.fxb then
        			local of = 1 - timer / 180
        			for i = 1, 16 do
        				SetImageState('bossring2' .. i, 'mul+add',
        					Color(1.9 * alpha, b.fxr * of, b.fxg * of, b.fxb * of))
                    end
        		else
        			for i = 1, 16 do
        				SetImageState('bossring2' .. i, 'mul+add',
        					Color(alpha, 255, 255, 255))
        			end
        		end
        		misc.RenderRing('bossring1', ringx, ringy,
        			timer * (main_radius / 90) + main_radius * 1.5 * sin(timer * 2) + 14 + exr1 + bold,
        			timer * (main_radius / 90) + main_radius * 1.5 * sin(timer * 2) - 2 + exr1,
        			-b.ani * rov, cut, 16)
        		misc.RenderRing('bossring2', ringx, ringy,
        			90 + ((main_radius - 90) / 90) * timer + 4,
        			-main_radius + (1 - cos(timer) ^ 2) * (main_radius * 2 - 12) - bold,
        			b.ani * rov, cut, 16)--white
        	else
        		if b.fxr and b.fxg and b.fxb then
        			for i = 1, 16 do
        				SetImageState('bossring2' .. i, 'mul+add',
        					Color(1.9 * alpha, b.fxr / 2, b.fxg / 2, b.fxb / 2))
        			end
        		else
        			for i = 1, 16 do
        				SetImageState('bossring2' .. i, 'mul+add',
        					Color(alpha, 255, 255, 255))
        			end
        		end
        		local t = b.t3 * extend_rate --多给点收缩时间,符卡环最终半径不要为0
        		misc.RenderRing('bossring1', ringx, ringy,
        			(t - timer * 1.08) / (t - 90) * main_radius + 14 + exr1 + bold,
        			(t - timer * 1.08) / (t - 90) * main_radius - 2 + exr1,
        			-b.ani * rov, cut, 16)
        		misc.RenderRing('bossring2', ringx, ringy,
        			(t - timer) / (t - 90) * main_radius + 4,
        			(t - timer) / (t - 90) * main_radius - 12 - bold,
        			b.ani * rov, cut, 16)--white
        	end
        end
    else
    end
end
