_editor_tasks["liu_10_mc_BossCard5_at"]=function(x1, y1, x2, y2)
    return function()
        local self=task.GetSelf()
        y1 = 224 - y1
        local da=(0)
        local x=(x2 - x1)
        local y=(y2 - y1)
        local px=(player.x - x1)
        local py=(player.y - y1)
        local j=((x * py) - (y * px))
        if j > 0 then
            da = -12
        else
            da = 12
        end
        x = x / 60
        y = y / 60
        local a=(-90 + (ran:Float(-180, 180) / 16))
        for _=1,61 do
            liu_10_mc.bullet.ShotBulletMode(1, 0, _editor_class["liu_10_mc_BossCard5 Bullet01"], x1, y1, 0, 0, 0, 0, 0, 1, 1, 0, 1, a, 0, {a})
            x1 = x1 + x
            y1 = y1 + y
            a = a + da
        end
    end
end
