_editor_class["liu_10_mc_BossCard6 Bullet01"]=Class(bullet)
_editor_class["liu_10_mc_BossCard6 Bullet01"].init=function(self,_x,_y,co, da, v, a)
bullet.init(self,liu_10_mc.bullet.bullet_class,COLOR_RED,true,true)
self.x,self.y=_x,_y
    _object.set_color(self,"mul+add",255,255,255,255)
    liu_10_mc.bullet.BulletClassInit(self, 10, co)
    liu_10_mc.bullet.SetBulletPreimg(self, 1, false)
    self.group = GROUP_INDES
    self.bound = false
    lasttask=task.New(self,function()
        PlaySound("kira00",0.1,self.x/256,false)
        lasttask=task.New(self,function()
            do
                local vv=self._speed local _d_vv=(-0.008333334)
                local aa=self._angle local _d_aa=(da)
                for _=1,60 do
                    task._Wait(1)
                    SetV2(self,vv,aa,true,false)
                    vv=vv+_d_vv
                    aa=aa+_d_aa
                end
            end
            do
                local aa=self._angle local _d_aa=(da / 4.8)
                for _=1,_infinite do
                    task._Wait(1)
                    SetV2(self,self._speed,aa,true,false)
                    aa=aa+_d_aa
                end
            end
        end)
        lasttask=task.New(self,function()
            for _=1,_infinite do
                task._Wait(1)
                self.x = self.x + v * cos(a)
                self.y = self.y + v * sin(a)
            end
        end)
    end)
end
