_editor_class["liu_10_mc_BossCard6_atLine"].init=function(self,_x,_y,v, a, list)
    self.x,self.y=_x,_y
    self.img="img_void"
    self.layer=LAYER_PLAYER_BULLET-5
    self.group=GROUP_GHOST
    self.hide=false
    self.bound=false
    self.navi=false
    self.hp=10
    self.maxhp=10
    self.colli=true
    self._servants={}
    self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.list = list
    self.r, self.n = 0, 48
    self.co = {48, 48, 255}
    self.alpha = 0
    lasttask=task.New(self,function()
        SetV2(self,v,a,true,false)
    end)
end
_editor_class["liu_10_mc_BossCard6_atLine"].frame=function(self)
    self.class.base.frame(self)
    local list = self.list
    for i = 1, #list do
        if not IsValid(list[i]) then
            table.remove(list, i)
        else
        end
    end
    for i = 1, #list do
        if IsValid(list[i]) then
            self.r = Dist(self.x, self.y, list[i].x, list[i].y)
            do break end
        else
        end
    end
    if #list <= 0 then
        _del(self,false)
    else
    end
    self.alpha = 0 + 192 * min(self.timer / 60, 1)
end
_editor_class["liu_10_mc_BossCard6_atLine"].render=function(self)
    local x, y = self.x, self.y
    local r, n = (self.r + 0.5), self.n
    local r2 = max(self.r - 0.5, 0)
    local a, da = 0, 360 / n
    local c = Color(self.alpha, unpack(self.co))
    SetImageState("white", "mul+add", c)
    for i = 1, n do
    	Render4V("white",
    		x + r * cos(a), y + r * sin(a), 0.5,
    		x + r * cos(a + da), y + r * sin(a + da), 0.5,
    		x + r2 * cos(a + da), y + r2 * sin(a + da), 0.5,
    		x + r2 * cos(a), y + r2 * sin(a), 0.5)
    	a = a + da
    end
    SetImageState("white", "", Color(0xFFFFFFFF))
end
_editor_class["liu_10_mc_BossCard6_atLine"].kill=function(self)
    local w = lstg.world
    if BoxCheck(self, w.l, w.r, w.b, w.t) then
        PlaySound("enep00",0.1,self.x/256,false)
        liu_10_mc.effect.CreateEnmKillEffect(self, 1)
    else
    end
end
