        task._Wait(60)
        PlaySound("explode",0.3,self.x/256,false)
        liu_10_mc.wisys.SetHitBox(self._wisys, 80, 80)
        local t = 300
        local way = 24
        local i = 0
        local max_t = 7200
        local j = 0
        local k = 0
        local m = 1
        self.co = 6
        for _=1,_infinite do
            max_t = max_t - t
            print(max_t)
            da = -1.8
            if j == 0 then
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x - 114, self.y - 54, 0 - da, way, k))
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x + 114, self.y - 54, da, way, k))
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x - 64, self.y + 80, da, way, k))
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x + 64, self.y + 80, 0 - da, way, k))
                j = 1
                k = 1 - k
            else
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x - 114, self.y - 54, da, way, k))
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x + 114, self.y - 54, 0 - da, way, k))
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x - 64, self.y + 80, 0 - da, way, k))
                lasttask=task.New(self,_editor_tasks["liu_10_mc_BossCard6_at"](self.x + 64, self.y + 80, da, way, k))
                j = 0
            end
            task._Wait(t)
            if i == 0 then
                if self.hp < 5000 / 1.5 then
                    t = 250
                    way = 24
                    PlaySound("explode",0.1,self.x/256,false)
                    i = 1
                    self.co = 8
                else
                end
            elseif i == 1 then
                if self.hp < 4000 / 1.5 then
                    t = 230
                    way = 26
                    PlaySound("explode",0.1,self.x/256,false)
                    i = 2
                    self.co = 13
                else
                end
