stage.group.DefStageFunc('liu_10_mc@'..__WEEK_ID,'init',function(self)
    _init_item(self)
    difficulty=self.group.difficulty
    New(mask_fader,'open')
    if jstg then jstg.CreatePlayers() else New(_G[lstg.var.player_name]) end
    lasttask=task.New(self,function()
        liu_10_mc.bullet.LoadTexResouces()
        liu_10_mc.bullet.LoadBulletResouces()
        liu_10_mc.effect.LoadTexResouces()
        liu_10_mc.stgenm.LoadTexResouces()
        liu_10_mc_screen()
        liu_10_mc_Distortion_CaptureAndDraw(LAYER_BG - 2, LAYER_BG + 4)
        LoadMusicRecord("bgm:liu_10_mc_th12_13")
        _play_music("bgm:liu_10_mc_th12_13")
        New(liu_10_mc.world)
        task._Wait(60)
        local _boss_wait=true
        local _ref=New(_editor_class["liu_10_mc_boss"],_editor_class["liu_10_mc_boss"].cards)
        last=_ref
        if _boss_wait then while IsValid(_ref) do task.Wait() end end
        task._Wait(240)
    end)
    ui.lstg_weekly.stage_init(self)
    task.New(self,function()
        while coroutine.status(self.task[1])~='dead' do task.Wait() end
        stage.group.FinishReplay()
        New(mask_fader,'close')
        task.New(self,function()
            local _,bgm=EnumRes('bgm')
            for i=1,30 do
                for _,v in pairs(bgm) do
                    if GetMusicState(v)=='playing' then
                        SetBGMVolume(v,1-i/30)
                    end
                end
                task.Wait()
            end
        end)
        task.Wait(30)
        stage.group.FinishStage()
    end)
end)
